-- host-preference-notes (issue #53): the host's notes for Thyme, free-text
-- meeting preferences the guest's assistant uses to shape what it proposes.
-- Hand-written with `supabase migration new` to match supabase/schemas
-- (tables/host_accounts.sql, functions/clear_assistant_notes.sql,
-- triggers/host_accounts_clear_assistant_notes.sql); not generated by pg-delta
-- and not applied. Null until the host answers the setup step; an empty string
-- means the host has none.

ALTER TABLE "app"."host_accounts"
  ADD COLUMN "assistant_notes" text CHECK (char_length("assistant_notes") <= 1000),
  ADD COLUMN "assistant_notes_updated_at" timestamptz;

-- A deleted host keeps no notes (data-stewardship: deletion on request). The
-- trigger clears them on the write that marks the account deleted, so
-- app.operator_delete_host is unchanged.
CREATE FUNCTION "app"."clear_assistant_notes"()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = ''
AS $$
BEGIN
  IF NEW.deleted_at IS NOT NULL THEN
    NEW.assistant_notes := NULL;
    NEW.assistant_notes_updated_at := NULL;
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER "host_accounts_clear_assistant_notes"
BEFORE INSERT OR UPDATE ON "app"."host_accounts"
FOR EACH ROW
EXECUTE FUNCTION "app"."clear_assistant_notes"();

ALTER TABLE "app"."host_accounts"
  ADD CONSTRAINT "host_accounts_deleted_no_notes" CHECK ("deleted_at" IS NULL OR "assistant_notes" IS NULL);

-- The same function privileges pg-delta gives app.clear_sender_name.
REVOKE ALL ON FUNCTION "app"."clear_assistant_notes"() FROM PUBLIC;

REVOKE ALL ON FUNCTION "app"."clear_assistant_notes"() FROM "postgres";

GRANT EXECUTE ON FUNCTION "app"."clear_assistant_notes"() TO "postgres";
